71	// emptyIDGuard rejects requests whose documentID path segment is empty with a
72	// 400 JSON error instead of letting ServeMux emit its HTML redirect.
73	func emptyIDGuard(next http.Handler) http.Handler {
74		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
75			p := r.URL.Path
