94	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
95		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
96	
97		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
98		if err != nil || mediaType != "application/json" {
99			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
100			return
101		}
102	
103		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
104		var req postRequest
105		dec := json.NewDecoder(r.Body)
106		if err := dec.Decode(&req); err != nil {
107			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
108			return
109		}
110		// Reject trailing data after the JSON object.
111		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
112			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
113			return
114		}
115	
116		if req.DeviceID == "" {
117			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
118			return
119		}
120		if len(req.Changes) == 0 {
121			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
122			return
123		}
124	
125		changes := make([]store.Change, len(req.Changes))
126		seen := make(map[string]struct{}, len(req.Changes))
127		for i, c := range req.Changes {
128			if c.ID == "" {
129				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
130				return
131			}
132			if len(c.Payload) == 0 {
133				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
134				return
135			}
136			if _, dup := seen[c.ID]; dup {
137				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
138				return
139			}
140			seen[c.ID] = struct{}{}
141			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
142		}
143	
144		results, err := s.PostChanges(documentID, changes)
145		if err != nil {
146			var conflict *store.ErrConflict
147			if errors.As(err, &conflict) {
148				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
149				return
150			}
151			writeError(w, http.StatusInternalServerError, "failed to commit changes")
152			return
153		}
154	
155		writeJSON(w, http.StatusOK, map[string]any{"results": results})
156	}
