158	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
159		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
160	
161		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
