170		if err := dec.Decode(&req); err != nil {
171			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
172			return
173		}
174		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
175			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
176			return
177		}
178	
179		if req.DeviceID == "" {
180			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
181			return
182		}
183		// baseCursor must be present and a non-negative integer (no fractions,
184		// strings, booleans or null).
185		if len(req.BaseCursor) == 0 {
186			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
187			return
188		}
189		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
190		if !ok {
191			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
192			return
193		}
194		if req.Change == nil {
195			writeError(w, http.StatusBadRequest, "change must be an object")
196			return
197		}
198		if req.Change.ID == "" {
199			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
200			return
201		}
202		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
203			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
204			return
205		}
206	
207		result, err := s.MergeChange(documentID, baseCursor, store.Change{
208			ID:       req.Change.ID,
209			DeviceID: req.DeviceID,
210			Payload:  req.Change.Payload,
211		})
212		if err != nil {
213			var conflict *store.ErrConflict
214			switch {
215			case errors.Is(err, store.ErrStaleCursor):
216				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
217				return
218			case errors.As(err, &conflict):
219				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
220				return
221			default:
222				writeError(w, http.StatusInternalServerError, "failed to merge change")
223				return
224			}
225		}
226	
227		writeJSON(w, http.StatusOK, result)
228	}
229	
230	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,
231	// strings, booleans, null and negative numbers are rejected.
232	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
233		var n int64
234		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
235			return 0, false
236		}
237		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
238		// require the literal to contain no fraction or exponent.
239		trimmed := strings.TrimSpace(string(raw))
240		if trimmed == "" || trimmed[0] == '-' {
241			return 0, false
242		}
243		for _, c := range trimmed {
244			if c < '0' || c > '9' {
245				return 0, false
246			}
247		}
248		return n, true
249	}
250	
251	// isJSONObject reports whether raw decodes to a JSON object (not null, an
252	// array or a scalar).
253	func isJSONObject(raw json.RawMessage) bool {
254		var m map[string]json.RawMessage
255		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
256			return false
257		}
258		return true
259	}
