261	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
262		documentID := r.PathValue("documentID")
263		q := r.URL.Query()
264	
265		after := int64(0)
266		if raw := q.Get("after"); raw != "" {
267			v, err := strconv.ParseInt(raw, 10, 64)
268			if err != nil || v < 0 {
269				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
270				return
271			}
272			after = v
273		}
274	
275		limit := int64(defaultListLimit)
276		if raw := q.Get("limit"); raw != "" {
277			v, err := strconv.ParseInt(raw, 10, 64)
278			if err != nil || v < 1 || v > maxListLimit {
279				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
280				return
281			}
282			limit = v
283		}
284	
285		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
286		if err != nil {
287			writeError(w, http.StatusInternalServerError, "failed to list changes")
288			return
289		}
290	
291		writeJSON(w, http.StatusOK, map[string]any{
292			"changes":    changes,
293			"nextCursor": nextCursor,
294		})
295	}
296	
297	func writeJSON(w http.ResponseWriter, status int, v any) {
298		w.Header().Set("Content-Type", "application/json")
299		w.WriteHeader(status)
300		_ = json.NewEncoder(w).Encode(v)
301	}
302	
303	func writeError(w http.ResponseWriter, status int, message string) {
304		writeJSON(w, status, map[string]string{"error": message})
305	}
