1	// Package store persists document change batches in a SQLite database.
2	//
3	// Within a document every change has a client-supplied id. New ids receive a
4	// monotonically increasing cursor; re-posting an existing id is idempotent
5	// only when the deviceId and decoded JSON payload match, otherwise it is a
6	// conflict. Valid batches commit atomically, so cursors never repeat and no
7	// record is partially written, even under concurrent writers.
8	package store
9	
10	import (
11		"database/sql"
12		"encoding/json"
13		"errors"
14		"fmt"
15	
16		_ "modernc.org/sqlite"
17	)
18	
19	// ErrStaleCursor reports that a merge targets a base cursor for an unknown
20	// document, or a base cursor greater than the document's current cursor. The
21	// caller maps it to 400; nothing is written.
22	var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")
23	
24	// Change is one element of an inbound batch or one row of a listing.
25	type Change struct {
26		ID       string          // client-supplied change id, unique per document
27		DeviceID string          // originating device
28		Payload  json.RawMessage // decoded JSON value, stored verbatim
29	}
30	
31	// Result reports the outcome for one element of an accepted batch.
32	type Result struct {
33		ID      string `json:"id"`
34		Created bool   `json:"created"`
35		Cursor  int64  `json:"cursor"`
36	}
37	
38	// ListedChange is one row in a ListChanges response.
39	type ListedChange struct {
40		ID       string          `json:"id"`
41		DeviceID string          `json:"deviceId"`
42		Payload  json.RawMessage `json:"payload"`
43		Cursor   int64           `json:"cursor"`
44	}
45	
46	// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
47	// of "idempotent", "applied" or "merged".
48	type MergeResult struct {
49		ID      string  `json:"id"`
50		Outcome string  `json:"outcome"`
51		Cursor  int64   `json:"cursor"`
52		Result  *Result `json:"result,omitempty"`
53	}
54	
55	// ErrConflict reports that a batch references an existing change id with a
56	// different deviceId or payload. The whole batch is rejected.
57	type ErrConflict struct {
58		ID string
59	}
60	
61	func (e *ErrConflict) Error() string {
62		return fmt.Sprintf("conflicting change %q for document", e.ID)
63	}
64	
65	// Store is the durable change log.
66	type Store struct {
67		db *sql.DB
68	}
69	
70	// Open opens (creating if needed) the SQLite database at path. The empty path
71	// opens an in-memory database useful for tests.
72	func Open(path string) (*Store, error) {
73		if path == "" {
74			// With a single pooled connection this is a private, per-instance
75			// in-memory database (useful for tests).
76			path = "file::memory:"
77		}
78		// _txlock=immediate makes writers acquire the write lock at BEGIN, so
79		// concurrent batches serialize without SQLITE_BUSY deadlocks.
80		dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
81		db, err := sql.Open("sqlite", dsn)
82		if err != nil {
83			return nil, err
84		}
85		// One connection avoids cross-connection locking surprises; writes are
86		// serialized by the immediate transaction anyway, and SQLite concurrency
87		// for readers does not help correctness here.
88		db.SetMaxOpenConns(1)
89		s := &Store{db: db}
90		if err := s.init(); err != nil {
91			_ = db.Close()
92			return nil, err
93		}
94		return s, nil
95	}
96	
97	func (s *Store) init() error {
98		_, err := s.db.Exec(`
99	CREATE TABLE IF NOT EXISTS changes (
100		document_id TEXT NOT NULL,
101		cursor      INTEGER NOT NULL,
102		id          TEXT NOT NULL,
103		device_id   TEXT NOT NULL,
104		payload     BLOB NOT NULL,
105		PRIMARY KEY (document_id, id)
106	);
107	CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
108		ON changes(document_id, cursor);
109	`)
110		return err
111	}
112	
113	// Close releases the database handle.
114	func (s *Store) Close() error { return s.db.Close() }
115	
116	// PostChanges validates and commits one batch atomically.
117	//
118	// Every change must have a non-empty id; duplicate ids within the batch are
119	// rejected by the caller before reaching this point. On conflict the returned
120	// error is *ErrConflict and nothing is written. Cursors are assigned in batch
121	// order to ids that do not yet exist. Results are returned in the same order
122	// as the input.
123	func (s *Store) PostChanges(documentID string, changes []Change) ([]Result, error) {
124		tx, err := s.db.Begin()
125		if err != nil {
126			return nil, err
127		}
128		defer func() { _ = tx.Rollback() }()
129	
130		results := make([]Result, len(changes))
131	
132		// First pass: resolve every id against existing rows. A single mismatch
133		// aborts the whole batch before any cursor is allocated.
134		pending := make([]int, 0, len(changes))
135		for i, c := range changes {
136			var existingDevice string
137			var existingPayload []byte
138			var existingCursor int64
139			err := tx.QueryRow(
140				`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
141				documentID, c.ID,
142			).Scan(&existingCursor, &existingDevice, &existingPayload)
143			switch {
144			case errors.Is(err, sql.ErrNoRows):
145				pending = append(pending, i)
146			case err != nil:
147				return nil, err
148			default:
149				if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
150					return nil, &ErrConflict{ID: c.ID}
151				}
152				results[i] = Result{
153					ID:      c.ID,
154					Created: false,
155					Cursor:  existingCursor,
156				}
157			}
158		}
159	
160		// Allocate cursors for genuinely new ids.
161		var nextCursor int64
162		if err := tx.QueryRow(
163			`SELECT COALESCE(MAX(cursor), 0) + 1 FROM changes WHERE document_id = ?`,
164			documentID,
165		).Scan(&nextCursor); err != nil {
166			return nil, err
167		}
168		for _, i := range pending {
169			c := changes[i]
170			if _, err := tx.Exec(
171				`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
172				documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
173			); err != nil {
174				return nil, err
175			}
176			results[i] = Result{
177				ID:      c.ID,
178				Created: true,
179				Cursor:  nextCursor,
180			}
181			nextCursor++
182		}
183	
184		if err := tx.Commit(); err != nil {
185			return nil, err
186		}
187		return results, nil
188	}
189	
190	// MergeChange validates and appends one change against a caller-observed base
191	// cursor, all within a single serialized transaction.
192	//
193	//   - An existing id is idempotent only when deviceId and the decoded payload
194	//     match (Outcome "idempotent", with the original Result); a mismatch is an
195	//     *ErrConflict and nothing is written.
196	//   - A new id with baseCursor equal to the current cursor is appended as
197	//     "applied".
198	//   - A new id with a base cursor behind the current one is appended as
199	//     "merged" only when every change after baseCursor carries a JSON object
200	//     payload whose top-level keys are disjoint from the new payload's; any
201	//     non-object later payload or shared key is an *ErrConflict.
202	//
203	// A non-zero baseCursor for an unknown document, or a baseCursor greater than
204	// the current cursor, returns ErrStaleCursor. An unknown document with
205	// baseCursor 0 accepts the first change as "applied".
206	func (s *Store) MergeChange(documentID string, baseCursor int64, c Change) (MergeResult, error) {
207		tx, err := s.db.Begin()
208		if err != nil {
209			return MergeResult{}, err
210		}
211		defer func() { _ = tx.Rollback() }()
212	
213		// Current cursor is the document's high-water mark, 0 when unknown.
214		var current int64
215		if err := tx.QueryRow(
216			`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
217			documentID,
218		).Scan(&current); err != nil {
219			return MergeResult{}, err
220		}
221		if baseCursor > current || (baseCursor != 0 && current == 0) {
222			return MergeResult{}, ErrStaleCursor
223		}
224	
225		// An existing id keeps the original idempotency/conflict rules.
226		var existingDevice string
227		var existingPayload []byte
228		var existingCursor int64
229		err = tx.QueryRow(
230			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
231			documentID, c.ID,
232		).Scan(&existingCursor, &existingDevice, &existingPayload)
233		switch {
234		case errors.Is(err, sql.ErrNoRows):
235			// New id; fall through to append logic below.
236		case err != nil:
237			return MergeResult{}, err
238		default:
239			if existingDevice != c.DeviceID || !jsonEqual(existingPayload, c.Payload) {
240				return MergeResult{}, &ErrConflict{ID: c.ID}
241			}
242			return MergeResult{
243				ID:      c.ID,
244				Outcome: "idempotent",
245				Cursor:  existingCursor,
246				Result: &Result{
247					ID:      c.ID,
248					Created: false,
249					Cursor:  existingCursor,
250				},
251			}, nil
252		}
253	
254		outcome := "applied"
255		if baseCursor < current {
256			// Merge is allowed only when every change after baseCursor is a JSON
257			// object whose top-level keys do not collide with the new payload's.
258			newKeys, err := objectKeys(c.Payload)
259			if err != nil {
260				if errors.Is(err, errNotObject) {
261					return MergeResult{}, &ErrConflict{ID: c.ID}
262				}
263				return MergeResult{}, err
264			}
265			rows, err := tx.Query(
266				`SELECT payload FROM changes
267				 WHERE document_id = ? AND cursor > ?
268				 ORDER BY cursor ASC`,
269				documentID, baseCursor,
270			)
271			if err != nil {
272				return MergeResult{}, err
273			}
274			for rows.Next() {
275				var laterPayload []byte
276				if err := rows.Scan(&laterPayload); err != nil {
277					_ = rows.Close()
278					return MergeResult{}, err
279				}
280				laterKeys, err := objectKeys(laterPayload)
281				if err != nil {
282					_ = rows.Close()
283					if errors.Is(err, errNotObject) {
284						return MergeResult{}, &ErrConflict{ID: c.ID}
285					}
286					return MergeResult{}, err
287				}
288				for k := range newKeys {
289					if _, clash := laterKeys[k]; clash {
290						_ = rows.Close()
291						return MergeResult{}, &ErrConflict{ID: c.ID}
292					}
293				}
294			}
295			if err := rows.Err(); err != nil {
296				_ = rows.Close()
297				return MergeResult{}, err
298			}
299			_ = rows.Close()
300			outcome = "merged"
301		}
302	
303		next := current + 1
304		if _, err := tx.Exec(
305			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
306			documentID, next, c.ID, c.DeviceID, []byte(c.Payload),
307		); err != nil {
308			return MergeResult{}, err
309		}
310	
311		if err := tx.Commit(); err != nil {
312			return MergeResult{}, err
313		}
314		return MergeResult{ID: c.ID, Outcome: outcome, Cursor: next}, nil
315	}
316	
317	// errNotObject marks a payload that is not a JSON object.
318	var errNotObject = errors.New("payload is not a JSON object")
319	
320	// objectKeys returns the top-level keys of a JSON object payload. A null,
321	// array or scalar payload yields errNotObject.
322	func objectKeys(raw json.RawMessage) (map[string]struct{}, error) {
323		var m map[string]json.RawMessage
324		if err := json.Unmarshal(raw, &m); err != nil {
325			// Valid JSON that is not an object (array, scalar, null) decodes with
326			// a type error into a map; treat it and malformed JSON as non-object.
327			return nil, errNotObject
328		}
329		if m == nil {
330			return nil, errNotObject
331		}
332		keys := make(map[string]struct{}, len(m))
333		for k := range m {
334			keys[k] = struct{}{}
335		}
336		return keys, nil
337	}
338	
339	// ListChanges returns at most limit changes for documentID whose cursor is
340	// greater than after, in cursor order, together with the cursor to pass as
341	// the next after value. An unknown document yields an empty list and cursor 0;
342	// a known document with no rows past after yields nextCursor == after.
343	func (s *Store) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
344		rows, err := s.db.Query(
345			`SELECT id, device_id, payload, cursor FROM changes
346			 WHERE document_id = ? AND cursor > ?
347			 ORDER BY cursor ASC
348			 LIMIT ?`,
349			documentID, after, limit,
350		)
351		if err != nil {
352			return nil, 0, err
353		}
354		defer func() { _ = rows.Close() }()
355	
356		out := make([]ListedChange, 0)
357		var maxCursor int64 = after
358		for rows.Next() {
359			var c ListedChange
360			if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
361				return nil, 0, err
362			}
363			out = append(out, c)
364			maxCursor = c.Cursor
365		}
366		if err := rows.Err(); err != nil {
367			return nil, 0, err
368		}
369	
370		// Distinguish an unknown document from a known one with nothing new:
371		// unknown documents must report nextCursor 0.
372		if len(out) == 0 {
373			var known bool
374			if err := s.db.QueryRow(
375				`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)`,
376				documentID,
377			).Scan(&known); err != nil {
378				return nil, 0, err
379			}
380			if !known {
381				return out, 0, nil
382			}
383		}
384		return out, maxCursor, nil
385	}
386	
387	// jsonEqual reports whether two payloads are equal after JSON decoding, so
388	// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal.
389	func jsonEqual(a, b json.RawMessage) bool {
390		var va, vb any
391		if err := json.Unmarshal(a, &va); err != nil {
392			return false
393		}
394		if err := json.Unmarshal(b, &vb); err != nil {
395			return false
396		}
397		return deepEqual(va, vb)
398	}
399	
400	func deepEqual(a, b any) bool {
401		switch av := a.(type) {
402		case nil:
403			return b == nil
404		case bool:
405			bv, ok := b.(bool)
406			return ok && av == bv
407		case string:
408			bv, ok := b.(string)
409			return ok && av == bv
410		case float64:
411			bv, ok := b.(float64)
412			return ok && av == bv
413		case []any:
414			bv, ok := b.([]any)
415			if !ok || len(av) != len(bv) {
416				return false
417			}
418			for i := range av {
419				if !deepEqual(av[i], bv[i]) {
420					return false
421				}
422			}
423			return true
424		case map[string]any:
425			bv, ok := b.(map[string]any)
426			if !ok || len(av) != len(bv) {
427				return false
428			}
429			for k, v := range av {
430				w, exists := bv[k]
431				if !exists || !deepEqual(v, w) {
432					return false
433				}
434			}
435			return true
436		default:
437			return false
438		}
439	}
