func TestSnapshotRetryAndConflictHTTP(t *testing.T) {
	h, _ := newTestHandler(t)
	seedDoc(t, h, "doc1", 1)

	w, body := postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1}}`)
