	// Decoded-equal retry (different key order and number format) is idempotent.
	w, body = postJSON(t, h, "/v1/documents/doc1/snapshots", `{"cursor":1,"state":{"v":1.0}}`)
	if w.Code != http.StatusOK || body["created"] != false {
